function fdcHomeSpellLibrary(){
 const storageKey='fdc-homebrew-spell-library-v1',migrationKey='fdc-homebrew-spell-library-schema';
 let entries=[];try{const saved=JSON.parse(localStorage.getItem(storageKey));if(Array.isArray(saved))entries=saved;}catch(e){}
 let needsMigration=false;try{needsMigration=localStorage.getItem(migrationKey)!=='4';}catch(e){}
 for(const spell of FDC_HOME_SPELLS){
  const existing=entries.find(x=>x.id===spell.id);
  if(existing){if(needsMigration){delete existing.status;delete existing.origin;Object.assign(existing,structuredClone(spell));}continue;}
  if(!entries.some(x=>String(x.name).toLocaleLowerCase('fr')===spell.name.toLocaleLowerCase('fr')))entries.push(structuredClone(spell));
 }
 try{localStorage.setItem(storageKey,JSON.stringify(entries));localStorage.setItem(migrationKey,'4');}catch(e){}
 return entries;
}

