const FDC_HOME_MONSTERS=[{"id":"maison-heritage-gobelin","name":"Gobelin","hp":20,"ca":12,"force":2,"adresse":1,"esprit":1,"description":"L’Héritage des Silences · Règles maison","abilities":"PV : 20 | CA : 12\nFOR 2 | ADR 1 | ESP 1\nAttaque mêlée : 1d6 + FOR.\nAttaque distance : 1d4 + ADR.","source":{"title":"L’Héritage des Silences – Bestiaire (MJ)","file":"LHeritage_des_Silences_Bestiaire_v2.pdf","page":1}},{"id":"maison-heritage-gobelin-chaman","name":"Gobelin Chaman","hp":18,"ca":11,"force":1,"adresse":1,"esprit":3,"description":"L’Héritage des Silences · Règles maison","abilities":"PV : 18 | CA : 11\nFOR 1 | ADR 1 | ESP 3\nATTAQUES\nBâton rituel (mêlée) : toucher +1 (FOR) ; dégâts 1D6+1.\nÉclair spirituel (distance magique, 9 m) : toucher +3 (ESP) ; dégâts 1D4+3.\nPOUVOIRS — une action par tour, à la place d'une attaque\nMalédiction du mauvais œil — utilisable une seule fois par combat (portée 9 m) : cible jet ESP DD 15 ; échec : désavantage à sa prochaine attaque avant la fin de son prochain tour.\nFumée protectrice — utilisable une seule fois par combat (rayon 3 m) : jusqu'au prochain tour du chaman, les gobelins dans la fumée gagnent +2 CA contre les attaques à distance. Ne se cumule pas.\nCri de ralliement — utilisable une seule fois par combat : un gobelin allié à 9 m récupère 1D6 PV, sans dépasser son maximum.\nRÈGLE : aucun pouvoir ne cause de dégâts supplémentaires ; pas de cumul de pouvoirs dans un même tour.","source":{"title":"L’Héritage des Silences – Bestiaire (MJ)","file":"LHeritage_des_Silences_Bestiaire_v2.pdf","page":1}},{"id":"maison-heritage-araignee-geante","name":"Araignée Géante","hp":15,"ca":10,"force":3,"adresse":2,"esprit":1,"description":"L’Héritage des Silences · Règles maison","abilities":"PV : 15 | CA : 10\nFOR 3 | ADR 2 | ESP 1\nMorsure : 1d6 + FOR.\nCrochet venimeux : 1d10 + ADR.\nOption MJ : poison léger (désavantage narratif temporaire).","source":{"title":"L’Héritage des Silences – Bestiaire (MJ)","file":"LHeritage_des_Silences_Bestiaire_v2.pdf","page":1}},{"id":"maison-heritage-squelette","name":"Squelette","hp":15,"ca":10,"force":3,"adresse":2,"esprit":1,"description":"L’Héritage des Silences · Règles maison","abilities":"PV : 15 | CA : 10\nFOR 3 | ADR 2 | ESP 1\nAttaque mêlée : 1d6 + FOR.\nAttaque distance : 1d4 + ADR.\nRésurgence Macabre : à 0 PV, jet d’ESPRIT DD 15. Succès : le squelette se relève avec 5 PV.","source":{"title":"L’Héritage des Silences – Bestiaire (MJ)","file":"LHeritage_des_Silences_Bestiaire_v2.pdf","page":1}},{"id":"maison-heritage-abomination-chaos","name":"Abomination du Chaos","hp":90,"ca":16,"force":7,"adresse":4,"esprit":4,"description":"L’Héritage des Silences · Règles maison","abilities":"PV : 90 | CA : 16\nFOR 7 | ADR 4 | ESP 4\nGriffure : 1d10 + FOR + 1d4 dégâts nécrotiques.\nJet d’acide (distance) : 1d6 + ADR + 1d4 poison.\nAction légendaire — Vague d’effroi : déclenchement hors tour quand menacée (PV < 45). Jet d’ESPRIT DD 12. Échec : la cible est terrifiée et perd son prochain tour.\nAction spéciale — Festin des Ombres : dévore une créature alliée, récupère 2d6 PV.","source":{"title":"L’Héritage des Silences – Bestiaire (MJ)","file":"LHeritage_des_Silences_Bestiaire_v2.pdf","page":1}},{"id":"maison-heritage-harpie-recifs","name":"Harpie des récifs","hp":22,"ca":12,"force":2,"adresse":4,"esprit":2,"description":"L’Héritage des Silences · Règles maison · Partie 2","abilities":"PV : 22 | CA : 12\nFOR 2 | ADR 4 | ESP 2\nATTAQUES\nGriffes (mêlée) : toucher +2 (FOR) ; dégâts 1D6+2.\nPlumes tranchantes (distance, 12 m) : toucher +4 (ADR) ; dégâts 1D4+4.\nPOUVOIR\nChant envoûtant (1/combat, portée 12 m) : une cible jet ESP DD 15 ; échec : elle perd sa prochaine attaque, mais peut se déplacer. Remplace l'attaque de la harpie.\nTACTIQUE : vole entre le mât et le pont ; une seule attaque par tour.","source":{"title":"L’Héritage des Silences – Bestiaire (MJ)","file":"FDC Console MJ – Partie 2","page":1}},{"id":"maison-heritage-troll-hauteurs","name":"Troll des hauteurs","hp":45,"ca":13,"force":5,"adresse":1,"esprit":0,"description":"L’Héritage des Silences · Règles maison · Partie 2","abilities":"PV : 45 | CA : 13\nFOR 5 | ADR 1 | ESP 0\nATTAQUES\nMassue (mêlée) : toucher +5 (FOR) ; dégâts 1D10+5.\nPoing (mêlée) : toucher +5 (FOR) ; dégâts 1D6+5.\nBousculade (mêlée) : toucher +5 (FOR) ; dégâts 1D4+5 et repousse la cible de 2 m.\nCAPACITÉ\nRégénération : récupère 3 PV au début de son tour, sauf s'il a subi du feu depuis son précédent tour. Maximum 45 PV.\nUne seule attaque par tour. Deux trolls utilisent cette même fiche.","source":{"title":"L’Héritage des Silences – Bestiaire (MJ)","file":"FDC Console MJ – Partie 2","page":1}},{"id":"maison-heritage-pouaah","name":"POUAAH — Troll colossal","hp":85,"ca":15,"force":8,"adresse":1,"esprit":2,"description":"L’Héritage des Silences · Règles maison · Partie 2","abilities":"PV : 85 | CA : 15\nFOR 8 | ADR 1 | ESP 2\nATTAQUES\nMarteau colossal (mêlée) : toucher +8 (FOR) ; dégâts 1D12+8.\nPoing de géant (mêlée) : toucher +8 (FOR) ; dégâts 1D8+8.\nFrappe au sol (1/combat, zone de 2 m) : cibles jet ADR DD 15 ; échec : 1D6+8 dégâts et renversées ; réussite : aucun dégât, pas de chute. Remplace l'attaque.\nCAPACITÉ\nRégénération : récupère 5 PV au début de son tour, sauf s'il a subi du feu depuis son précédent tour. Maximum 85 PV.\nPNJ : ami d'enfance d'Argg, allié potentiel. Affronter les trois trolls simultanément est très dangereux.","source":{"title":"L’Héritage des Silences – Bestiaire (MJ)","file":"FDC Console MJ – Partie 2","page":1}},{"id":"maison-heritage-reine-araignees","name":"Matriarche des toiles","hp":48,"ca":14,"force":5,"adresse":3,"esprit":4,"description":"L’Héritage des Silences · Reine des araignées · Boss ou PNJ · Partie 2","abilities":"PV : 48 | CA : 14\nFOR 5 | ADR 3 | ESP 4\n\nATTAQUES — une seule attaque par tour\n**Mandibules venimeuses** (corps à corps) : **+5 pour toucher** (Force) ; **dégâts 1D8+5** perforants. Si elle touche, la cible fait un jet de **FORCE DD 15** : échec, **+1D4 dégâts de poison** ; réussite, aucun dégât de poison supplémentaire.\n**Pattes perforantes** (corps à corps) : **+5 pour toucher** (Force) ; **dégâts 1D6+5** perforants.\n**Projection de toile** (distance 9 m) : **+3 pour toucher** (Adresse) ; aucun dégât. Si elle touche, cible immobilisée. Pour se libérer, la cible dépense son action et réussit **FORCE DD 15** ; nouvelle tentative possible à chaque tour.\n\nATTAQUES LÉGENDAIRES — chacune utilisable une seule fois par combat\n**Toile de la Matriarche** (1 fois par combat) : projette une toile dans un rayon de 3 m, à 9 m maximum. Chaque créature présente fait **FORCE DD 15** ; échec : immobilisée, aucun dégât. Pour se libérer, utiliser son action et réussir **FORCE DD 15**, nouvelle tentative à chaque tour. Remplace l'attaque du tour.\n**Venin paralysant** (1 fois par combat) : après une morsure réussie, remplace le poison ordinaire par un venin spécial. La cible fait **FORCE DD 15** ; échec : paralysée jusqu'à la fin de son prochain tour ; réussite : pas de paralysie. Les **dégâts 1D8+5** de la morsure restent appliqués. Ne rajoute pas 1D4 de poison.\n**Appel de la colonie** (1 fois par combat) : appelle une araignée géante ordinaire (**15 PV, CA 10**) qui arrive au tour suivant. Remplace l'attaque du tour ; uniquement si le MJ décide que la rencontre est hostile.\n\nRÈGLES MJ : une attaque ou une attaque légendaire par tour, jamais les deux (sauf Venin paralysant qui modifie la morsure). La Matriarche peut discuter avec Dory et Mavis ; le combat n'est pas obligatoire.","source":{"title":"L’Héritage des Silences – Bestiaire (MJ)","file":"FDC Console MJ – Partie 2","page":1}}];
function fdcHomeMonsterLibrary(){
 let entries=[];try{const saved=JSON.parse(localStorage.getItem('fdc-homebrew-monster-library-v1'));if(Array.isArray(saved))entries=saved;}catch(e){}
 for(const profile of FDC_HOME_MONSTERS){
  const existing=entries.find(x=>x.id===profile.id);
  if(!existing){entries.push(structuredClone(profile));continue;}
  if(profile.id==='maison-heritage-gobelin-chaman' && (String(existing.abilities||'').includes('Sort mineur : malédiction légère (désavantage narratif 1 tour).') || (String(existing.abilities||'').includes('Malédiction du mauvais œil (1/combat') && String(existing.abilities||'').includes('Fumée protectrice (1/combat'))))Object.assign(existing,structuredClone(profile));
  if(profile.id==='maison-heritage-reine-araignees' && (existing.name==='Reine des araignées' || existing.name==='Matriarche des étoiles'))Object.assign(existing,structuredClone(profile));
 }
 try{localStorage.setItem('fdc-homebrew-monster-library-v1',JSON.stringify(entries));}catch(e){}
 return entries;
}

function fdcHomeMonsterStatData(t){
 const text=String(t?.abilities||''),description=String(t?.description||''),scores={};
 const name=String(t?.name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 // Older copies of the three Mont Chaud monsters may have no structured stats.
 // Never overwrite a numeric value explicitly saved by the MJ.
 const montChaud=name.includes('morzhael')&&name.includes('silence incandescent')?[9,2,5]:
   name.includes('caillouchon tortue')?[4,-1,0]:
   name.includes('caillouchon ordinaire')?[2,-2,-1]:null;
 for(const [idx,key,field] of [['0','FOR','force'],['1','ADR','adresse'],['2','ESP','esprit']]){
  const keys=key==='ESP'?'(?:ESP|INT)':'(?:'+key+')';
  const pattern=new RegExp('(?:^|[^A-Z])'+keys+'\\s*:?\\s*([+−-]?\\d+)','i');
  const raw=text.match(pattern),described=description.match(pattern);
  const saved=t?.[field];
  const value=Number.isFinite(saved)?saved:
    (typeof saved==='string'&&saved.trim()!==''&&Number.isFinite(Number(saved))?Number(saved):
    raw?Number(raw[1].replace('−','-')):
    described?Number(described[1].replace('−','-')):
    montChaud?montChaud[Number(idx)]:null);
  if(value!==null&&Number.isFinite(value))scores[key]={score:value,modifier:value};
 }
 const abilities=text.replace(/^PV\\s*:[^\\n]*\\n/,'').replace(/^FOR\\s*[+−-]?\\d+\\s*\\|\\s*ADR\\s*[+−-]?\\d+\\s*\\|\\s*ESP\\s*[+−-]?\\d+\\s*\\n?/,'');
 return {scores,prefix:'',abilities};
}
function fdcHomeMonsterStats(t,editable=false){
 const data=fdcMonsterStatData(t),names=[['FOR','Force'],['ADR','Adresse'],['ESP','Esprit']];
 return '<table class="monster-stats'+(editable?' monster-stats-edit':'')+'"><thead><tr>'+names.map(([key,label])=>'<th scope="col">'+label+'</th>').join('')+'</tr></thead><tbody><tr>'+names.map(([key,label])=>{const value=data.scores[key]?.score??'';return editable?'<td><input id="editStat'+key+'" class="monster-stat-input" type="number" step="1" aria-label="'+label+'" value="'+value+'"></td>':'<td><span class="stat-score">'+(value===''?'—':value)+'</span></td>';}).join('')+'</tr></tbody></table>';
}
function fdcHomeSaveMonsterAbilities(textareaId='editAb'){
 const parts=[];
 for(const name of ['FOR','ADR','ESP']){const input=$('editStat'+name);if(!input||input.value==='')continue;const n=Number(input.value);if(!Number.isInteger(n)||n< -999||n>999)throw Error('Valeur invalide pour '+name);parts.push(name+' '+n);}
 return (parts.length?parts.join(' | ')+'\n':'')+$(textareaId).value;
}
function fdcHomeCombatStats(doc){
 doc=doc.replace(/function fdcMonsterStatData\(t\)\{[\s\S]*?(?=function fdcStatModifier)/,fdcHomeMonsterStatData.toString().replace('fdcHomeMonsterStatData','fdcMonsterStatData')+'\n');
 doc=doc.replace(/function fdcMonsterStats\(t,editable=false\)\{[\s\S]*?(?=function fdcUpdateStatModifier)/,fdcHomeMonsterStats.toString().replace('fdcHomeMonsterStats','fdcMonsterStats')+'\n');
 doc=doc.replace(/function fdcSaveMonsterAbilities\(textareaId='editAb'\)\{[\s\S]*?(?=function fdcMonsterImageButton)/,fdcHomeSaveMonsterAbilities.toString().replace('fdcHomeSaveMonsterAbilities','fdcSaveMonsterAbilities')+'\n');
 return doc;
}

function fdcIsDriveVisualUrl(url){
 try{const link=new URL(url);return link.origin==='https://drive.google.com'&&link.pathname.startsWith('/file/d/');}catch{return false;}
}

FDC_HOME_MONSTERS.push(...EMERAUDE.combat.bestiary);
